/** POOL-029：员工使用规则版本、就绪校验与 Key/Grant 原子发布。 */
import { createHash, randomUUID } from "node:crypto";
import { sql, type Kysely, type Transaction } from "kysely";
import { matchApplicableBillingRule, type BillingResourceMode } from "@qianliu/domain";
import type {
  Database,
  EmployeeModelTarget,
} from "../kysely.js";
import type { EmployeeModelPoolQuota } from "../employee-model-rule-types.js";
import {
  validateEmployeeModelRule,
  type EmployeeModelRuleVersion,
  type RuleValidationResult,
} from "./employee-model-rule-validation.js";
import { lockActiveProviderPools } from "./principal-access-locks.js";
import { captureManualBaseline, lockRuleFamily, lockVersion, providerCodesForRuleFamily } from "./employee-model-rule-lock-context.js";
import { resolvePoolQuota } from "./employee-model-rule-quota.js";
import { disableEmployeeRuleVersion, refreshEmployeeKeyModels } from "./employee-model-rule-lifecycle.js";
import { listEnabledBillingRulesAt } from "./billing-rule-applicability.js";
import { recordEmployeeQuotaChange, employeeQuotaChangeContext } from "./principal-access-quota-management.js";

export function publishRequestHash(quotaMode: "SET" | "ADD" | undefined) {
  return createHash("sha256").update(JSON.stringify({ quota_mode: quotaMode ?? "SET" })).digest("hex");
}

export type {
  EmployeeModelRuleVersion,
  RulePermissionChange,
  RuleReadinessIssue,
  RuleValidationResult,
} from "./employee-model-rule-validation.js";

export interface EmployeeModelRuleInput {
  name: string;
  employee_scope: "SELECTED" | "ALL";
  principal_ids: string[];
  model_scope: "SELECTED" | "ALL";
  model_targets: EmployeeModelTarget[];
  quota_value: bigint;
  allow_overage: boolean;
  valid_from: Date;
  valid_until: Date | null;
  /** POOL-035：厂商级池额度；空数组表示无厂商级额度，发布时回退版本级单值。 */
  pool_quotas: EmployeeModelPoolQuota[];
}

export class EmployeeModelRuleError extends Error {
  constructor(
    readonly code: "NOT_FOUND" | "CONFLICT" | "NOT_READY" | "INVALID_STATE" | "IDEMPOTENCY_CONFLICT",
    message: string,
    readonly validation?: RuleValidationResult,
  ) {
    super(message);
    this.name = "EmployeeModelRuleError";
  }
}

function jsonValue<T>(value: T): T {
  return JSON.stringify(value) as unknown as T;
}

export class EmployeeModelRuleRepository {
  constructor(private readonly db: Kysely<Database>) {}

  async catalog(enterpriseId: string) {
    const [principals, routes] = await Promise.all([
      this.db.selectFrom("principal")
        .leftJoin("principal_key", (join) => join
          .onRef("principal_key.principal_id", "=", "principal.id")
          .onRef("principal_key.enterprise_id", "=", "principal.enterprise_id")
          .on("principal_key.status", "=", "ACTIVE"))
        .select([
          "principal.id", "principal.name", "principal.department_label", "principal.status",
          "principal.archived_at", "principal_key.id as active_key_id",
        ])
        .where("principal.enterprise_id", "=", enterpriseId)
        .where("principal.type", "=", "EMPLOYEE")
        // 排除已归档主体（POOL-008/009 验收遗留），与 validation 的 archived_at 语义一致；
        // DISABLED 但未归档的主体仍列出标灰，那是"临时停用、可恢复"的正常业务状态。
        .where("principal.archived_at", "is", null)
        .orderBy("principal.name")
        .execute(),
      this.db.selectFrom("model_route")
        .innerJoin("unified_model", "unified_model.id", "model_route.unified_model_id")
        .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
        .innerJoin("provider", "provider.id", "provider_resource.provider_id")
        .select([
          "unified_model.id as unified_model_id", "unified_model.alias", "unified_model.display_name",
          "unified_model.status as model_status", "model_route.id as route_id", "model_route.upstream_model",
          "model_route.enabled as route_enabled", "provider_resource.id as provider_resource_id",
          "provider_resource.name as resource_name", "provider_resource.status as resource_status",
          "provider_resource.mode", "provider.code as provider_code", "provider.name as provider_name",
          "provider.status as provider_status",
        ])
        .where("model_route.enterprise_id", "=", enterpriseId)
        // ACTIVE 和新接入的 PENDING_CONFIG 型号都返回：后者在主体页显示
        // “未就绪”及缺口，但不能被授权。旧笼统别名通过 DISABLED/归档隐藏，
        // 不再借 route.enabled 同时承担“待配置可见性”和“可服务”两种语义。
        .where("unified_model.status", "in", ["ACTIVE", "PENDING_CONFIG"])
        .where("unified_model.archived_at", "is", null)
        .where("model_route.archived_at", "is", null)
        .orderBy("provider.name")
        .orderBy("unified_model.display_name")
        .execute(),
    ]);
    const now = new Date();
    const billing = await listEnabledBillingRulesAt(this.db, enterpriseId, now);
    return {
      principals: principals.map((principal) => ({
        ...principal,
        ready: principal.status === "ACTIVE" && principal.archived_at === null && principal.active_key_id !== null,
        unavailable_reason: principal.status !== "ACTIVE" || principal.archived_at !== null
          ? "员工主体未启用"
          : principal.active_key_id === null ? "员工尚无有效 Key" : null,
      })),
      models: routes.map((route) => {
        const hasBilling = matchApplicableBillingRule(
          billing,
          route.provider_resource_id,
          route.upstream_model,
          route.mode as BillingResourceMode,
          now.getTime(),
        ) !== null;
        const reasons = [
          route.model_status !== "ACTIVE" ? "统一模型未启用" : null,
          !route.route_enabled ? "Model Route 未启用" : null,
          !["ACTIVE", "DEGRADED"].includes(route.resource_status) ? "厂商资源不可服务" : null,
          route.provider_status !== "ACTIVE" ? "厂商未启用" : null,
          !hasBilling ? "缺少当前生效的计价或扣减规则" : null,
        ].filter((reason): reason is string => Boolean(reason));
        return { ...route, ready: reasons.length === 0, unavailable_reasons: reasons };
      }),
    };
  }

  async list(enterpriseId: string): Promise<EmployeeModelRuleVersion[]> {
    return this.db.selectFrom("employee_model_rule_version").selectAll()
      .where("enterprise_id", "=", enterpriseId)
      .orderBy("created_at", "desc").execute();
  }

  async history(enterpriseId: string, ruleId: string): Promise<EmployeeModelRuleVersion[]> {
    return this.db.selectFrom("employee_model_rule_version").selectAll()
      .where("enterprise_id", "=", enterpriseId).where("rule_id", "=", ruleId)
      .orderBy("version", "desc").execute();
  }

  async create(enterpriseId: string, adminUserId: string, input: EmployeeModelRuleInput) {
    return this.db.insertInto("employee_model_rule_version").values({
      enterprise_id: enterpriseId,
      rule_id: randomUUID(),
      version: 1,
      name: input.name,
      employee_scope: input.employee_scope,
      principal_ids: jsonValue(input.principal_ids),
      model_scope: input.model_scope,
      model_targets: jsonValue(input.model_targets),
      quota_value: input.quota_value,
      allow_overage: input.allow_overage,
      valid_from: input.valid_from,
      valid_until: input.valid_until,
      pool_quotas: jsonValue(input.pool_quotas),
      created_by_admin_user_id: adminUserId,
    }).returningAll().executeTakeFirstOrThrow();
  }

  async createNextVersion(enterpriseId: string, adminUserId: string, ruleId: string) {
    return this.db.transaction().execute(async (trx) => {
      const latest = await trx.selectFrom("employee_model_rule_version").selectAll()
        .where("enterprise_id", "=", enterpriseId).where("rule_id", "=", ruleId)
        .orderBy("version", "desc").forUpdate().executeTakeFirst();
      if (!latest) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则不存在");
      if (latest.status === "DRAFT" || latest.status === "VALIDATED") {
        throw new EmployeeModelRuleError("CONFLICT", "该规则已有未发布版本");
      }
      return trx.insertInto("employee_model_rule_version").values({
        enterprise_id: enterpriseId, rule_id: ruleId, version: latest.version + 1,
        name: latest.name, employee_scope: latest.employee_scope,
        principal_ids: jsonValue(latest.principal_ids), model_scope: latest.model_scope,
        model_targets: jsonValue(latest.model_targets), quota_value: latest.quota_value,
        allow_overage: latest.allow_overage, valid_from: latest.valid_from,
        valid_until: latest.valid_until, pool_quotas: jsonValue(latest.pool_quotas ?? []),
        created_by_admin_user_id: adminUserId,
      }).returningAll().executeTakeFirstOrThrow();
    });
  }

  async updateDraft(enterpriseId: string, versionId: string, expectedLockVersion: number, input: EmployeeModelRuleInput) {
    const updated = await this.db.updateTable("employee_model_rule_version").set({
      name: input.name, employee_scope: input.employee_scope,
      principal_ids: jsonValue(input.principal_ids), model_scope: input.model_scope,
      model_targets: jsonValue(input.model_targets), quota_value: input.quota_value,
      allow_overage: input.allow_overage, valid_from: input.valid_from,
      valid_until: input.valid_until, pool_quotas: jsonValue(input.pool_quotas),
      status: "DRAFT", validation_snapshot: null,
      lock_version: sql`lock_version + 1`, updated_at: new Date(),
    }).where("enterprise_id", "=", enterpriseId).where("id", "=", versionId)
      .where("status", "in", ["DRAFT", "VALIDATED"]).where("lock_version", "=", expectedLockVersion)
      .returningAll().executeTakeFirst();
    if (!updated) throw new EmployeeModelRuleError("CONFLICT", "规则已被修改或当前版本不可编辑，请刷新后重试");
    return updated;
  }

  async validate(enterpriseId: string, versionId: string): Promise<RuleValidationResult> {
    return this.db.transaction().execute(async (trx) => {
      const version = await lockVersion(trx, enterpriseId, versionId);
      if (!version) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则版本不存在");
      if (!["DRAFT", "VALIDATED"].includes(version.status)) {
        throw new EmployeeModelRuleError("INVALID_STATE", "只有草稿或已校验版本可以重新校验");
      }
      const validation = await validateEmployeeModelRule(trx, version);
      await trx.updateTable("employee_model_rule_version").set({
        status: validation.ready ? "VALIDATED" : "DRAFT",
        validation_snapshot: jsonValue(validation) as unknown as Record<string, unknown>, lock_version: sql`lock_version + 1`, updated_at: new Date(),
      }).where("id", "=", version.id).execute();
      return validation;
    });
  }

  async publish(input: {
    enterpriseId: string; versionId: string; expectedLockVersion: number;
    idempotencyKey: string; adminUserId: string;
    /** POOL-033 §6：SET（默认）= 池额度设为规则值；ADD = 行锁内追加规则值。 */
    quotaMode?: "SET" | "ADD";
  }): Promise<{ version: EmployeeModelRuleVersion; validation: RuleValidationResult; assignment_count: number }> {
    return this.db.transaction().execute(async (trx) => {
      const requestHash = publishRequestHash(input.quotaMode);
      const { reference, principals } = await lockRuleFamily(
        trx, input.enterpriseId, input.versionId,
        captureManualBaseline,
      );
      if (!reference) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则版本不存在");
      const version = await this.lockRuleVersion(trx, input.enterpriseId, input.versionId);
      const reusedKey = await trx.selectFrom("employee_model_rule_version").select(["id", "rule_id"])
        .where("enterprise_id", "=", input.enterpriseId)
        .where("publish_idempotency_key", "=", input.idempotencyKey)
        .where("id", "!=", version.id).executeTakeFirst();
      if (reusedKey) {
        throw new EmployeeModelRuleError("IDEMPOTENCY_CONFLICT", "该发布幂等键已被其他规则版本使用");
      }
      if (version.status === "PUBLISHED") {
        if (version.publish_idempotency_key !== input.idempotencyKey) {
          throw new EmployeeModelRuleError("IDEMPOTENCY_CONFLICT", "该版本已使用其他幂等键发布");
        }
        // 0043 前的历史行没有 request hash，只兼容默认 SET 重放；显式 ADD
        // 必须拿到新的幂等键，避免相同 key 携带不同额度语义时静默 no-op。
        if (version.publish_request_hash !== requestHash
          && (version.publish_request_hash !== null || input.quotaMode === "ADD")) {
          throw new EmployeeModelRuleError("IDEMPOTENCY_CONFLICT", "该发布幂等键对应的额度模式不同");
        }
        const count = await trx.selectFrom("employee_model_rule_assignment")
          .select((eb) => eb.fn.countAll<number>().as("count"))
          .where("rule_version_id", "=", version.id).executeTakeFirstOrThrow();
        return { version, validation: version.validation_snapshot as unknown as RuleValidationResult, assignment_count: Number(count.count) };
      }
      if (version.status !== "VALIDATED") {
        throw new EmployeeModelRuleError("INVALID_STATE", "请先校验通过，再显式发布规则");
      }
      if (version.lock_version !== input.expectedLockVersion) {
        throw new EmployeeModelRuleError("CONFLICT", "规则已被修改，请刷新并重新校验");
      }
      const validation = await validateEmployeeModelRule(trx, version);
      if (!validation.ready) throw new EmployeeModelRuleError("NOT_READY", "规则就绪校验未通过", validation);

      const providerCodes = await providerCodesForRuleFamily(
        trx, input.enterpriseId, version.rule_id, version.model_scope, version.model_targets,
      );
      await lockActiveProviderPools(trx, input.enterpriseId, principals, providerCodes);

      const previous = await trx.selectFrom("employee_model_rule_version").select("id")
        .where("enterprise_id", "=", input.enterpriseId).where("rule_id", "=", version.rule_id)
        .where("status", "=", "PUBLISHED").where("id", "!=", version.id).forUpdate().execute();
      // 新版本发布是增量授权：旧版本只退役 assignment 所有权，不把未选型号写入
      // 显式禁用清单；真正撤权只能走单独的“停用”动作。
      for (const item of previous) {
        await disableEmployeeRuleVersion(trx, input.enterpriseId, item.id, false);
      }

      for (const principalId of [...validation.principal_ids].sort()) {
        // POOL-033：规则只管型号准入开关，额度归主体×厂商池。每主体每厂商至多一个 ACTIVE 池
        // （由迁移 0039 唯一索引保证）；本规则发布只确保池存在（不存在则建空池待管理员填额度），
        // 随后所有该厂商下的 target 共享同一池 grant_id。
        const targetByProvider = new Map<string, {
          unified_model_id: string; provider_resource_id: string; alias: string; mode: string;
        }[]>();
        for (const target of validation.model_targets) {
          const route = await trx.selectFrom("model_route")
            .innerJoin("unified_model", "unified_model.id", "model_route.unified_model_id")
            .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
            .innerJoin("provider", "provider.id", "provider_resource.provider_id")
            .select(["unified_model.alias", "provider.code", "provider_resource.mode"])
            .where("model_route.enterprise_id", "=", input.enterpriseId)
            .where("model_route.unified_model_id", "=", target.unified_model_id)
            .where("model_route.provider_resource_id", "=", target.provider_resource_id)
            .where("model_route.enabled", "=", true).executeTakeFirstOrThrow();
          const bucket = targetByProvider.get(route.code) ?? [];
          bucket.push({ unified_model_id: target.unified_model_id, provider_resource_id: target.provider_resource_id,
            alias: route.alias, mode: route.mode });
          targetByProvider.set(route.code, bucket);
        }
        for (const [providerCode, targets] of targetByProvider) {
          // POOL-035：该厂商的池额度——优先厂商级 pool_quotas，否则回退版本级单值。
          const providerQuota = (version.pool_quotas ?? []).find((item) => item.provider_code === providerCode);
          const poolQuota = resolvePoolQuota(version, providerCode);
          // 查找或建立该主体×厂商的 ACTIVE 池 Grant。
          let poolGrant = await trx.selectFrom("principal_grant").select("id")
            .where("enterprise_id", "=", input.enterpriseId)
            .where("principal_id", "=", principalId)
            .where("provider", "=", providerCode)
            .where("pool_model_alias", "=", "*")
            .where("status", "=", "ACTIVE")
            .forUpdate()
            .executeTakeFirst();
          const { basis, before: beforeQuota } = await employeeQuotaChangeContext(trx, {
            enterpriseId: input.enterpriseId, principalId, provider: providerCode,
            modes: targets.map((target) => target.mode), grantId: poolGrant?.id ?? null,
            basisError: (message) => new EmployeeModelRuleError("NOT_READY", message),
          });
          if (!poolGrant) {
            // 建池：用该厂商的额度（厂商级优先，回退版本级）。单人页保存时规则额度为 NULL，池额度由
            // 编排端点单独管理。并发安全：唯一索引冲突时重查（另一事务已建池）。
            const inserted = await trx.insertInto("principal_grant").values({
              enterprise_id: input.enterpriseId, principal_id: principalId, provider: providerCode,
              model_alias: "*", pool_model_alias: "*", quota_unit: "TOKEN",
              quota_value: poolQuota.quota_value,
              quota_basis: basis,
              allow_overage: poolQuota.allow_overage, valid_from: version.valid_from, valid_until: poolQuota.valid_until,
              status: "ACTIVE", authorization_rule_version_id: version.id,
            }).onConflict((oc) => oc.doNothing()).returning("id").executeTakeFirst();
            if (inserted) {
              poolGrant = inserted;
              await trx.insertInto("quota_counter").values({ grant_id: poolGrant.id }).execute();
            } else {
              // 冲突：另一事务已建池，重新查询。
              poolGrant = await trx.selectFrom("principal_grant").select("id")
                .where("enterprise_id", "=", input.enterpriseId)
                .where("principal_id", "=", principalId)
                .where("provider", "=", providerCode)
                .where("pool_model_alias", "=", "*")
                .where("status", "=", "ACTIVE")
                .forUpdate()
                .executeTakeFirstOrThrow();
            }
          } else if (input.quotaMode === "ADD") {
            // POOL-033 §6 + POOL-035：批量"追加额度"——按厂商分别锁内追加；厂商级缺失时要求
            // 版本级 quota_value 非 NULL，否则该厂商无可追加的额度。
            if (!providerQuota && version.quota_value === null) {
              throw new EmployeeModelRuleError("INVALID_STATE", `厂商 ${providerCode} 缺少可追加的额度`);
            }
            await trx.updateTable("principal_grant")
              .set({ quota_value: sql`quota_value + ${poolQuota.quota_value}`, authorization_rule_version_id: version.id,
                quota_basis: beforeQuota?.quota_basis ?? basis,
                version: sql`version + 1`, updated_at: new Date() })
              .where("id", "=", poolGrant.id).execute();
          } else {
            await trx.updateTable("principal_grant").set({
              quota_value: poolQuota.quota_value, allow_overage: poolQuota.allow_overage,
              quota_basis: beforeQuota?.quota_basis ?? basis,
              valid_until: poolQuota.valid_until, authorization_rule_version_id: version.id,
              version: sql`version + 1`, updated_at: new Date(),
            }).where("id", "=", poolGrant.id).execute();
          }
          await recordEmployeeQuotaChange(trx, {
            enterpriseId: input.enterpriseId, principalId, provider: providerCode,
            grantId: poolGrant.id, adminUserId: input.adminUserId,
            action: input.quotaMode, before: beforeQuota,
          });
          // 每个 target 建一条型号级行（pool_model_alias=NULL）用于"准入开关 + 池回退查询"，
          // 不再独立计数；assignment 指向池 grant_id。
          for (const t of targets) {
            await trx.insertInto("employee_model_rule_assignment").values({
              enterprise_id: input.enterpriseId, rule_version_id: version.id, principal_id: principalId,
              unified_model_id: t.unified_model_id, provider_resource_id: t.provider_resource_id,
              grant_id: poolGrant.id, status: "ACTIVE",
            }).execute();
          }
        }
        await this.refreshKeyModels(trx, input.enterpriseId, principalId);
      }

      const published = await trx.updateTable("employee_model_rule_version").set({
        status: "PUBLISHED", validation_snapshot: jsonValue(validation) as unknown as Record<string, unknown>,
        publish_idempotency_key: input.idempotencyKey, publish_request_hash: requestHash, published_at: new Date(),
        lock_version: sql`lock_version + 1`, updated_at: new Date(),
      }).where("id", "=", version.id).returningAll().executeTakeFirstOrThrow();
      await trx.insertInto("operation_log").values({ actor_source: "ADMIN",
        enterprise_id: input.enterpriseId, admin_user_id: input.adminUserId,
        action: "employee_model_rule.publish", target_type: "employee_model_rule",
        target_id: version.rule_id, result: "SUCCESS", failure_reason: null,
        change_summary: jsonValue({ version: version.version, principal_count: validation.principal_count,
          model_count: validation.model_count, assignment_count: validation.assignment_count,
          quota_mode: input.quotaMode ?? "SET" }),
      }).execute();
      return { version: published, validation, assignment_count: validation.assignment_count };
    });
  }

  async disable(enterpriseId: string, versionId: string, adminUserId: string) {
    return this.db.transaction().execute(async (trx) => {
      const { reference, principals } = await lockRuleFamily(
        trx, enterpriseId, versionId,
        captureManualBaseline,
      );
      if (!reference) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则版本不存在");
      const version = await this.lockRuleVersion(trx, enterpriseId, versionId);
      if (version.status === "DISABLED") return version;
      if (version.status !== "PUBLISHED") {
        throw new EmployeeModelRuleError("INVALID_STATE", "只有已发布规则可以停用");
      }
      const providerCodes = await providerCodesForRuleFamily(
        trx, enterpriseId, version.rule_id, version.model_scope, version.model_targets,
      );
      await lockActiveProviderPools(trx, enterpriseId, principals, providerCodes);
      const affected = await disableEmployeeRuleVersion(trx, enterpriseId, version.id);
      await trx.insertInto("operation_log").values({ actor_source: "ADMIN",
        enterprise_id: enterpriseId, admin_user_id: adminUserId,
        action: "employee_model_rule.disable", target_type: "employee_model_rule",
        target_id: version.rule_id, result: "SUCCESS", failure_reason: null,
        change_summary: jsonValue({ version: version.version, principal_ids: affected }),
      }).execute();
      return trx.selectFrom("employee_model_rule_version").selectAll().where("id", "=", version.id)
        .executeTakeFirstOrThrow();
    });
  }

  /** 同一业务规则的发布/停用串行化，必须在主体 Key 锁之后调用。 */
  private async lockRuleVersion(trx: Transaction<Database>, enterpriseId: string, versionId: string) {
    const reference = await trx.selectFrom("employee_model_rule_version").select("rule_id")
      .where("enterprise_id", "=", enterpriseId).where("id", "=", versionId).executeTakeFirst();
    if (!reference) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则版本不存在");
    await sql`SELECT pg_advisory_xact_lock(hashtext(${`${enterpriseId}:${reference.rule_id}`}))`.execute(trx);
    const version = await lockVersion(trx, enterpriseId, versionId);
    if (!version) throw new EmployeeModelRuleError("NOT_FOUND", "员工使用规则版本不存在");
    return version;
  }

  /** POOL-033：升级为 public，供 PrincipalAccessConfigRepository 同事务复用。 */
  async refreshKeyModels(trx: Transaction<Database>, enterpriseId: string, principalId: string) {
    return refreshEmployeeKeyModels(trx, enterpriseId, principalId);
  }
}

src/repositories/principal-access-config.source:
/** POOL-033：单主体接入配置编排仓储 —— 单人页唯一写入通道。
 *
 * 依据：设计草案 v2（`V3/Handoff/接入配置统一-后端数据合同设计草案v2-20260805.md`）。
 * - GET：装配"按厂商分块 + 池 + 型号开关 + 待接管标记"的读模型；
 * - PUT：单事务完成"校验 → 池 upsert → 型号开关版本化 → 手工接管 → 白名单重算 →
 *   审计 → 幂等存档"，任一步失败整体回滚。
 *
 * 权限模型（决策点④）：厂商下型号默认全开（新接入型号自动并入），掐型号走显式禁用
 * 清单 principal_provider_disabled_model。准入 = 厂商池 ACTIVE AND 型号不在禁用清单。
 *
 * 额度模型（决策点：池挂主体×厂商）：每主体每厂商至多一个 ACTIVE 池 Grant
 * （0039 唯一索引保证）。规则不再承载额度（quota_value 可空）。
 */
import type { Kysely, Transaction } from "kysely";
import { sql } from "kysely";
import type { Database } from "../kysely.js";
import { EmployeeModelRuleRepository } from "./employee-model-rule-repository.js";
import {
  lockActivePrincipalKeys,
  lockActiveProviderPools,
} from "./principal-access-locks.js";
import { ensureSingleRule } from "./principal-single-rule.js";
import { captureManualBaseline } from "./employee-model-rule-lock-context.js";
import {
  assemblePrincipalAccessReadModel,
  type PrincipalAccessModelRow,
  type PrincipalAccessPoolRow,
} from "./principal-access-read-model.js";
import { stableHash, stableProviderCodes } from "./principal-access-config-utils.js";
import { ensureCurrentQuotaPeriod } from "./employee-quota-repository.js";
import { principalAccessQuotaView } from "./principal-access-quota-view.js";
import { writePrincipalProviderPools, PrincipalAccessPoolBasisError } from "./principal-access-pool-writer.js";

export {
  computeAllowedModelIds,
  stableHash,
  stableProviderCodes,
} from "./principal-access-config-utils.js";

export class PrincipalAccessConfigError extends Error {
  constructor(
    readonly code: "NOT_FOUND" | "INVALID_STATE" | "CONFLICT" | "NOT_READY" | "IDEMPOTENCY_CONFLICT" | "INVALID_REQUEST",
    message: string,
    readonly detail?: unknown,
  ) {
    super(message);
    this.name = "PrincipalAccessConfigError";
  }
}

function jsonValue<T>(value: T): T {
  return JSON.stringify(value) as unknown as T;
}

export interface PoolSpec {
  provider_code: string;
  quota_value: bigint;
  allow_overage: boolean;
  valid_until: Date | null;
  /** 该厂商下要保留开通的型号（其余进入显式禁用清单）。空数组 = 不开通该厂商。 */
  enabled_model_ids: string[];
}

export interface AccessConfigPutInput {
  enterpriseId: string;
  principalId: string;
  adminUserId: string;
  expectedVersion: number;
  idempotencyKey: string;
  pools: PoolSpec[];
}

export class PrincipalAccessConfigRepository {
  private readonly ruleRepo: EmployeeModelRuleRepository;

  constructor(private readonly db: Kysely<Database>) {
    this.ruleRepo = new EmployeeModelRuleRepository(db);
  }

  /** GET 读模型：厂商分块 + 池 + 型号开关 + 待接管标记 + config_version。 */
  async read(enterpriseId: string, principalId: string) {
    return this.db.transaction().setIsolationLevel("repeatable read").execute((trx) =>
      new PrincipalAccessConfigRepository(trx).readSnapshot(enterpriseId, principalId));
  }

  private async readSnapshot(enterpriseId: string, principalId: string) {
    const now = new Date();
    const enterprise = await this.db.selectFrom("enterprise")
      .select(["timezone", "employee_quota_monthly_from"])
      .where("id", "=", enterpriseId).executeTakeFirstOrThrow();
    const principal = await this.db.selectFrom("principal")
      .select(["id", "type", "name", "status", "department_label", "archived_at"])
      .where("enterprise_id", "=", enterpriseId).where("id", "=", principalId)
      .executeTakeFirst();
    if (!principal) throw new PrincipalAccessConfigError("NOT_FOUND", "主体不存在");

    const key = await this.db.selectFrom("principal_key")
      .select(["id", "key_prefix", "status", "created_at", "allowed_model_ids"])
      .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
      .where("status", "=", "ACTIVE").executeTakeFirst();

    // 厂商目录（复用 029 catalog 的 models 部分语义，但按厂商分块）。
    const catalog = await this.ruleRepo.catalog(enterpriseId);
    const models = catalog.models as PrincipalAccessModelRow[];

    // 该主体的全部 ACTIVE 池。
    const poolRows = await this.db.selectFrom("principal_grant")
      .leftJoin("quota_counter", "quota_counter.grant_id", "principal_grant.id")
      .select([
        "principal_grant.id", "principal_grant.provider", "principal_grant.quota_value",
        "principal_grant.allow_overage", "principal_grant.valid_until",
        "principal_grant.quota_basis",
        "principal_grant.authorization_rule_version_id",
        sql<bigint>`COALESCE(quota_counter.used_value, 0)`.as("used_value"),
      ])
      .where("principal_grant.enterprise_id", "=", enterpriseId)
      .where("principal_grant.principal_id", "=", principalId)
      .where("principal_grant.pool_model_alias", "=", "*")
      .where("principal_grant.status", "=", "ACTIVE")
      .where("principal_grant.valid_from", "<=", now)
      .where((eb) => eb.or([
        eb("principal_grant.valid_until", "is", null),
        eb("principal_grant.valid_until", ">", now),
      ]))
      .execute();

    // 池来源判定：有 owner_principal_id 的单人规则版本 → MANAGED_SINGLE；否则批量。
    const singleRuleVersionIds = await this.singleRuleVersionIds(enterpriseId, principalId);
    const singleVersionSet = new Set(singleRuleVersionIds);
    const quotaByProvider = new Map<string, ReturnType<typeof principalAccessQuotaView>>();
    for (const row of principal.type === "EMPLOYEE"
      ? [...poolRows].sort((a, b) => a.provider.localeCompare(b.provider, "en")) : []) {
      const period = await ensureCurrentQuotaPeriod(this.db, { enterpriseId, principalId, provider: row.provider, now });
      quotaByProvider.set(row.provider, principalAccessQuotaView({
        period, basis: row.quota_basis, timezone: enterprise.timezone,
        effectiveFrom: enterprise.employee_quota_monthly_from,
      }));
    }
    const pools: PrincipalAccessPoolRow[] = poolRows.map((row) => ({
      id: row.id, provider: row.provider, quota_value: row.quota_value,
      allow_overage: row.allow_overage, valid_until: row.valid_until,
      used_value: row.used_value,
      quota: quotaByProvider.get(row.provider),
      source: row.authorization_rule_version_id === null
        ? "MANUAL_PENDING"
        : singleVersionSet.has(row.authorization_rule_version_id) ? "MANAGED_SINGLE" : "MANAGED_BATCH",
    }));

    // 显式禁用清单。
    const disabledRows = await this.db.selectFrom("principal_provider_disabled_model")
      .select(["provider", "unified_model_id"])
      .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
      .execute();
    const disabledSet = new Set(disabledRows.map((r) => `${r.provider}:${r.unified_model_id}`));

    const configuredAssignments = await this.db.selectFrom("employee_model_rule_assignment")
      .innerJoin("principal_grant", "principal_grant.id", "employee_model_rule_assignment.grant_id")
      .select("employee_model_rule_assignment.unified_model_id")
      .where("employee_model_rule_assignment.enterprise_id", "=", enterpriseId)
      .where("employee_model_rule_assignment.principal_id", "=", principalId)
      .where("employee_model_rule_assignment.status", "=", "ACTIVE")
      .where("principal_grant.status", "=", "ACTIVE")
      .execute();

    // 待接管手工基线。
    const manualPending = await this.db.selectFrom("principal_model_manual_authorization")
      .select("unified_model_id")
      .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
      .execute();

    // config_version。
    const state = await this.db.selectFrom("principal_access_config_state")
      .select("config_version")
      .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
      .executeTakeFirst();

    return assemblePrincipalAccessReadModel({
      principal: {
        id: principal.id,
        name: principal.name,
        status: principal.status,
        department_label: principal.department_label,
      },
      key,
      models,
      pools,
      disabledKeys: disabledSet,
      configuredModelIds: [
        ...(key?.allowed_model_ids ?? []),
        ...configuredAssignments.map((row) => row.unified_model_id),
      ],
      manualPendingIds: manualPending.map((row) => row.unified_model_id),
      configVersion: state?.config_version ?? 1,
    });
  }

  private async singleRuleVersionIds(enterpriseId: string, principalId: string): Promise<string[]> {
    const rows = await this.db.selectFrom("employee_model_rule_version")
      .select("id")
      .where("enterprise_id", "=", enterpriseId)
      .where("owner_principal_id", "=", principalId)
      .execute();
    return rows.map((r) => r.id);
  }

  /** PUT：单事务保存。详见模块头注释。 */
  async put(input: AccessConfigPutInput) {
    return this.db.transaction().execute(async (trx) => {
      // 1. 预校验：主体存在、ACTIVE、未归档、有 ACTIVE Key。
      const principal = await trx.selectFrom("principal")
        .select(["id", "type", "name", "status", "archived_at"])
        .where("enterprise_id", "=", input.enterpriseId).where("id", "=", input.principalId)
        .executeTakeFirst();
      if (!principal) throw new PrincipalAccessConfigError("NOT_FOUND", "主体不存在");
      const monthlyPolicy = principal.type === "EMPLOYEE"
        ? await trx.selectFrom("enterprise").select("employee_quota_monthly_from")
          .where("id", "=", input.enterpriseId).executeTakeFirst() : undefined;
      if (principal.status !== "ACTIVE" || principal.archived_at !== null) {
        throw new PrincipalAccessConfigError("INVALID_STATE", "主体已停用或归档，不能配置接入");
      }
      const lockedKeys = await lockActivePrincipalKeys(trx, input.enterpriseId, [input.principalId]);
      if (!lockedKeys.has(input.principalId)) {
        throw new PrincipalAccessConfigError("INVALID_STATE", "主体尚无有效 Key");
      }

      // 2. 幂等短路。
      const requestHash = stableHash({ pools: input.pools.map((p) => ({
        provider_code: p.provider_code, quota_value: p.quota_value.toString(),
        allow_overage: p.allow_overage, valid_until: p.valid_until, enabled_model_ids: [...p.enabled_model_ids].sort(),
      })) });
      const prior = await trx.selectFrom("principal_access_idempotency")
        .selectAll()
        .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
        .where("idempotency_key", "=", input.idempotencyKey).executeTakeFirst();
      if (prior) {
        if (prior.request_hash !== requestHash) {
          throw new PrincipalAccessConfigError("IDEMPOTENCY_CONFLICT", "该幂等键已用于不同请求");
        }
        return { ...prior.response_snapshot as Record<string, unknown>, replayed: true };
      }

      // 3. config_version 乐观锁（行锁内自增）。
      const locked = await this.lockAndCheckConfigVersion(trx, input);

      // 4. 就绪校验：pools 中每个 enabled_model_id 属该厂商且就绪。
      const catalog = await new EmployeeModelRuleRepository(trx).catalog(input.enterpriseId);
      const models = catalog.models as PrincipalAccessModelRow[];
      const modelById = new Map(models.map((m) => [m.unified_model_id, m]));
      const [configuredKey, configuredAssignments] = await Promise.all([
        trx.selectFrom("principal_key")
          .select("allowed_model_ids")
          .where("enterprise_id", "=", input.enterpriseId)
          .where("principal_id", "=", input.principalId)
          .where("status", "=", "ACTIVE")
          .executeTakeFirst(),
        trx.selectFrom("employee_model_rule_assignment")
          .innerJoin("principal_grant", "principal_grant.id", "employee_model_rule_assignment.grant_id")
          .select("employee_model_rule_assignment.unified_model_id")
          .where("employee_model_rule_assignment.enterprise_id", "=", input.enterpriseId)
          .where("employee_model_rule_assignment.principal_id", "=", input.principalId)
          .where("employee_model_rule_assignment.status", "=", "ACTIVE")
          .where("principal_grant.status", "=", "ACTIVE")
          .execute(),
      ]);
      const previouslyConfiguredModelIds = new Set([
        ...(configuredKey?.allowed_model_ids ?? []),
        ...configuredAssignments.map((row) => row.unified_model_id),
      ]);
      const issues: Array<{ code: string; message: string; unified_model_id?: string; provider_code?: string }> = [];
      for (const pool of input.pools) {
        const providerModels = models.filter((m) => m.provider_code === pool.provider_code);
        const enabledModes = new Set(providerModels
          .filter((model) => pool.enabled_model_ids.includes(model.unified_model_id)).map((model) => model.mode));
        if (monthlyPolicy?.employee_quota_monthly_from && enabledModes.size > 1) {
          issues.push({ code: "QUOTA_BASIS_CONFLICT", provider_code: pool.provider_code,
            message: `厂商 ${pool.provider_code} 同时包含 API 与套餐，月度额度计量基础须先明确` });
        }
        if (providerModels.length === 0) {
          issues.push({ code: "PROVIDER_UNAVAILABLE", provider_code: pool.provider_code, message: `厂商 ${pool.provider_code} 在本企业无可用型号` });
        }
        for (const modelId of pool.enabled_model_ids) {
          const m = modelById.get(modelId);
          if (!m || m.provider_code !== pool.provider_code) {
            issues.push({ code: "MODEL_UNAVAILABLE", unified_model_id: modelId, provider_code: pool.provider_code, message: `型号不属于厂商 ${pool.provider_code} 或不属于本企业` });
          } else if (!m.ready && !previouslyConfiguredModelIds.has(modelId)) {
            issues.push({ code: "MODEL_UNAVAILABLE", unified_model_id: modelId, provider_code: pool.provider_code, message: `型号 ${m.display_name} 未就绪：${m.unavailable_reasons.join("；")}` });
          }
        }
        if (pool.enabled_model_ids.length === 0 && pool.quota_value > 0n) {
          issues.push({ code: "INVALID_REQUEST", provider_code: pool.provider_code, message: `厂商 ${pool.provider_code} 给了额度但未勾选任何型号` });
        }
      }
      if (issues.length > 0) {
        throw new PrincipalAccessConfigError(
          "NOT_READY",
          issues[0]?.message ?? "接入配置就绪校验未通过",
          { issues },
        );
      }

      // 5. 手工接管先于池锁：Key 已在事务最前面锁定，旧白名单不会被并发发布覆盖。
      await captureManualBaseline(trx, input.enterpriseId, input.principalId);

      // 6. 规则行先锁定，随后按稳定 provider 顺序锁池。
      const singleRuleVersionId = await ensureSingleRule(trx, input);
      const currentPools = await trx.selectFrom("principal_grant")
        .select(["id", "provider", "quota_value", "authorization_rule_version_id"])
        .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
        .where("pool_model_alias", "=", "*").where("status", "=", "ACTIVE").execute();
      const providerCodes = stableProviderCodes(
        currentPools.map((pool) => pool.provider), input.pools.map((pool) => pool.provider_code),
      );
      const lockedPools = await lockActiveProviderPools(
        trx, input.enterpriseId, [input.principalId], providerCodes,
      );
      const currentByProvider = new Map(
        providerCodes
          .map((provider) => [provider, lockedPools.get(`${input.principalId}:${provider}`)] as const)
          .filter((entry): entry is readonly [string, NonNullable<typeof entry[1]>] => entry[1] !== undefined),
      );
      let written;
      try {
        written = await writePrincipalProviderPools(trx, input, currentByProvider, modelById,
          singleRuleVersionId, monthlyPolicy?.employee_quota_monthly_from ?? null, principal.type === "EMPLOYEE");
      } catch (error) {
        if (error instanceof PrincipalAccessPoolBasisError) throw new PrincipalAccessConfigError("NOT_READY", error.message);
        throw error;
      }
      const { changes, poolGrantByProvider } = written;

      // 7. 型号开关版本化（单人规则）+ 显式禁用清单重算。
      const allEnabledModelIds = new Set(input.pools.flatMap((p) => p.enabled_model_ids));
      const targets = [...allEnabledModelIds].map((modelId) => {
        const m = modelById.get(modelId)!;
        return { unified_model_id: modelId, provider_resource_id: m.provider_resource_id };
      });
      await this.publishSingleRuleVersion(trx, input, singleRuleVersionId, targets, poolGrantByProvider, modelById);

      // 8. 手工接管：清空基线（权限已由池+开关承载）。
      const manualCleared = await trx.deleteFrom("principal_model_manual_authorization")
        .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
        .executeTakeFirst();

      // 9. 重算白名单。
      await this.ruleRepo.refreshKeyModels(trx, input.enterpriseId, input.principalId);

      // 10. 审计 + 幂等存档。
      const response = {
        config_version: locked.nextVersion,
        changes,
        takeover: { cleared_manual: Number(manualCleared.numDeletedRows ?? 0) },
      };
      await trx.insertInto("operation_log").values({ actor_source: "ADMIN",
        enterprise_id: input.enterpriseId, admin_user_id: input.adminUserId,
        action: "principal_access_config.save", target_type: "principal",
        target_id: input.principalId, result: "SUCCESS", failure_reason: null,
        change_summary: jsonValue({
          config_version: locked.nextVersion, pools_added: changes.pools_added,
          pools_updated: changes.pools_updated, pools_closed: changes.pools_closed,
          enabled_models: allEnabledModelIds.size,
        }),
      }).execute();
      await trx.insertInto("principal_access_idempotency").values({
        enterprise_id: input.enterpriseId, principal_id: input.principalId,
        idempotency_key: input.idempotencyKey, request_hash: requestHash,
        response_snapshot: jsonValue(response) as Record<string, unknown>,
      }).execute();
      return response;
    });
  }

  /** 锁 config_version 行并比对 expectedVersion，通过后自增（在事务内）。 */
  private async lockAndCheckConfigVersion(trx: Transaction<Database>, input: AccessConfigPutInput) {
    await trx.insertInto("principal_access_config_state").values({
      enterprise_id: input.enterpriseId, principal_id: input.principalId, config_version: 1,
    }).onConflict((oc) => oc.doNothing()).execute();
    const state = await trx.selectFrom("principal_access_config_state")
      .select("config_version")
      .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
      .forUpdate().executeTakeFirstOrThrow();
    if (state.config_version !== input.expectedVersion) {
      throw new PrincipalAccessConfigError("CONFLICT", "配置已被其他操作修改，请刷新后重试");
    }
    const nextVersion = state.config_version + 1;
    await trx.updateTable("principal_access_config_state")
      .set({ config_version: nextVersion, updated_at: new Date() })
      .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
      .execute();
    return { nextVersion };
  }

  /** 发布单人规则新版本：禁用不再开通的型号、保留仍开通的、写显式禁用清单。 */
  private async publishSingleRuleVersion(
    trx: Transaction<Database>,
    input: AccessConfigPutInput,
    ruleVersionId: string,
    targets: { unified_model_id: string; provider_resource_id: string }[],
    poolGrantByProvider: Map<string, string>,
    modelById: Map<string, PrincipalAccessModelRow>,
  ) {
    const version = await trx.selectFrom("employee_model_rule_version").selectAll()
      .where("id", "=", ruleVersionId).forUpdate().executeTakeFirstOrThrow();

    // 撤掉旧 PUBLISHED 版本（若有）：其 assignment 置 DISABLED。
    const previousPublished = await trx.selectFrom("employee_model_rule_version").select("id")
      .where("enterprise_id", "=", input.enterpriseId).where("rule_id", "=", version.rule_id)
      .where("status", "=", "PUBLISHED").where("id", "!=", version.id).forUpdate().execute();
    for (const prev of previousPublished) {
      await trx.updateTable("employee_model_rule_assignment")
        .set({ status: "DISABLED", disabled_at: new Date() })
        .where("rule_version_id", "=", prev.id).where("status", "=", "ACTIVE").execute();
      await trx.updateTable("employee_model_rule_version")
        .set({ status: "DISABLED", disabled_at: new Date(), updated_at: new Date() })
        .where("id", "=", prev.id).execute();
    }

    // 更新当前版本为 VALIDATED → PUBLISHED，并落 targets。
    await trx.updateTable("employee_model_rule_version").set({
      model_targets: jsonValue(targets), status: "PUBLISHED",
      published_at: new Date(), lock_version: sql`lock_version + 1`, updated_at: new Date(),
    }).where("id", "=", version.id).execute();

    // 建 assignment（指向池 grant_id）。
    const targetKeys = new Set(targets.map((t) => `${t.unified_model_id}:${t.provider_resource_id}`));
    // 修复（POOL-033 回归）：同一规则版本内"掐型号"时，被掐型号的旧 assignment 必须停用。
    // 原实现只为 targets 建 assignment（onConflict doNothing），但不触碰本次未选中的旧 ACTIVE
    // assignment → refreshKeyModels 的 managed 来源仍含被掐型号 → 白名单冗余。
    // 虽 Gateway 禁用清单会兜底拒绝实际调用，但白名单冗余违反"静态授权集即真实可用集"语义，
    // 也让回归测试无法收紧断言。此处停用该规则版本下不在 targets 里的 ACTIVE assignment。
    const targetModelIds = new Set(targets.map((t) => t.unified_model_id));
    // targets 非空时停用被掐型号的旧 assignment（targets 为空时本函数不会走到这里——
    // 就绪校验拒绝 quota>0 但 enabled_model_ids 为空，且 poolGrantByProvider 为空时无池可挂）。
    if (targetModelIds.size > 0) {
      await trx.updateTable("employee_model_rule_assignment")
        .set({ status: "DISABLED", disabled_at: new Date() })
        .where("rule_version_id", "=", ruleVersionId)
        .where("status", "=", "ACTIVE")
        .where("unified_model_id", "not in", [...targetModelIds]).execute();
    }
    for (const target of targets) {
      const m = modelById.get(target.unified_model_id)!;
      const poolGrantId = poolGrantByProvider.get(m.provider_code);
      if (!poolGrantId) continue; // 池未建（enabled_model_ids 为空）则不建开关
      await trx.insertInto("employee_model_rule_assignment").values({
        enterprise_id: input.enterpriseId, rule_version_id: ruleVersionId,
        principal_id: input.principalId, unified_model_id: target.unified_model_id,
        provider_resource_id: target.provider_resource_id, grant_id: poolGrantId, status: "ACTIVE",
      }).onConflict((oc) => oc.doNothing()).execute();
    }

    // 显式禁用清单：该主体该厂商下"不就绪或未被本次保留"的型号。
    // 语义：已开通厂商中，未出现在 targets 里的型号全部进禁用清单。
    const enabledProviderCodes = new Set([...poolGrantByProvider.keys()]);
    for (const providerCode of enabledProviderCodes) {
      const providerModels = [...modelById.values()].filter((m) => m.provider_code === providerCode);
      for (const m of providerModels) {
        const key = `${m.unified_model_id}:${m.provider_resource_id}`;
        if (!targetKeys.has(key)) {
          await trx.insertInto("principal_provider_disabled_model").values({
            enterprise_id: input.enterpriseId, principal_id: input.principalId,
            provider: providerCode, unified_model_id: m.unified_model_id,
            disabled_at: new Date(), disable_rule_version_id: ruleVersionId,
          }).onConflict((oc) => oc.doNothing()).execute();
        }
      }
      // 重新开通的型号从禁用清单移除。
      const reEnabled = providerModels.filter((m) => targetKeys.has(`${m.unified_model_id}:${m.provider_resource_id}`));
      if (reEnabled.length > 0) {
        await trx.deleteFrom("principal_provider_disabled_model")
          .where("enterprise_id", "=", input.enterpriseId).where("principal_id", "=", input.principalId)
          .where("provider", "=", providerCode)
          .where("unified_model_id", "in", reEnabled.map((m) => m.unified_model_id)).execute();
      }
    }

    // 池被关闭的厂商：该厂商所有型号的禁用清单清空（无所谓，池 DISABLED 已整体拒）。
    // 无需额外动作——池 DISABLED 后 findAdmissibleGrant 不再命中。
  }
}

src/repositories/principal-access-pool-w.source:
import { sql, type Transaction } from "kysely";
import type { Database } from "../kysely.js";
import type { AccessConfigPutInput } from "./principal-access-config-repository.js";
import type { PrincipalAccessModelRow } from "./principal-access-read-model.js";
import type { LockedPrincipalGrant } from "./principal-access-locks.js";
import { recordEmployeeQuotaChange, assertCurrentQuotaBasis } from "./principal-access-quota-management.js";

export class PrincipalAccessPoolBasisError extends Error {}

/** Writer keeps the existing Key/provider lock order; no independent transaction. */
export async function writePrincipalProviderPools(
  trx: Transaction<Database>, input: AccessConfigPutInput,
  currentByProvider: Map<string, LockedPrincipalGrant>,
  modelById: Map<string, PrincipalAccessModelRow>,
  singleRuleVersionId: string, monthlyFrom: Date | null, isEmployee: boolean,
) {
const requestedProviders = new Set(input.pools.filter((p) => p.enabled_model_ids.length > 0).map((p) => p.provider_code));
const changes: { pools_added: string[]; pools_updated: string[]; pools_closed: string[] } = {
  pools_added: [], pools_updated: [], pools_closed: [],
};

// 5a. 关闭请求的 providers 之外的现有池。
for (const [provider, pool] of currentByProvider) {
  if (!requestedProviders.has(provider)) {
    await trx.updateTable("principal_grant")
      .set({ status: "DISABLED", version: sql`version + 1`, updated_at: new Date() })
      .where("id", "=", pool.id).execute();
    changes.pools_closed.push(provider);
    await recordEmployeeQuotaChange(trx, {
      enterpriseId: input.enterpriseId, principalId: input.principalId,
      provider, grantId: pool.id, adminUserId: input.adminUserId, action: "DISABLE", before: pool,
    });
  }
}

// 5b. upsert 请求的池。
const poolGrantByProvider = new Map<string, string>();
for (const pool of input.pools) {
  if (pool.enabled_model_ids.length === 0) continue;
  const existing = currentByProvider.get(pool.provider_code);
  const modes = new Set(pool.enabled_model_ids.map((id) => modelById.get(id)!.mode));
  const basis = modes.size === 1 ? (modes.has("API") ? "RAW_TOKEN" as const : "PLAN_QUOTA" as const) : null;
  if (monthlyFrom) await assertCurrentQuotaBasis(trx, {
    enterpriseId: input.enterpriseId, principalId: input.principalId, provider: pool.provider_code, basis,
    basisError: (message) => new PrincipalAccessPoolBasisError(message),
  });
  if (monthlyFrom && existing?.quota_basis && basis !== existing.quota_basis) {
    throw new PrincipalAccessPoolBasisError(`厂商 ${pool.provider_code} 的月度额度基础已确定，不能直接改为另一种计量方式`);
  }
  if (existing) {
    await trx.updateTable("principal_grant").set({
      quota_value: pool.quota_value, allow_overage: pool.allow_overage,
      valid_until: pool.valid_until,
      quota_basis: isEmployee ? basis : undefined,
      authorization_rule_version_id: singleRuleVersionId,
      version: sql`version + 1`, updated_at: new Date(),
    }).where("id", "=", existing.id).execute();
    poolGrantByProvider.set(pool.provider_code, existing.id);
    changes.pools_updated.push(pool.provider_code);
    await recordEmployeeQuotaChange(trx, {
      enterpriseId: input.enterpriseId, principalId: input.principalId,
      provider: pool.provider_code, grantId: existing.id, adminUserId: input.adminUserId, action: "SET", before: existing,
    });
  } else {
    const grant = await trx.insertInto("principal_grant").values({
      enterprise_id: input.enterpriseId, principal_id: input.principalId,
      provider: pool.provider_code, model_alias: "*", pool_model_alias: "*",
      quota_unit: "TOKEN", quota_value: pool.quota_value, allow_overage: pool.allow_overage,
      quota_basis: isEmployee ? basis : undefined,
      valid_until: pool.valid_until, status: "ACTIVE",
      authorization_rule_version_id: singleRuleVersionId,
    }).returning("id").executeTakeFirstOrThrow();
    await trx.insertInto("quota_counter").values({ grant_id: grant.id }).execute();
    poolGrantByProvider.set(pool.provider_code, grant.id);
    changes.pools_added.push(pool.provider_code);
    await recordEmployeeQuotaChange(trx, {
      enterpriseId: input.enterpriseId, principalId: input.principalId,
      provider: pool.provider_code, grantId: grant.id, adminUserId: input.adminUserId, action: "SET", before: null,
    });
  }
}

return { changes, poolGrantByProvider };
}

