import type { PrincipalAccessQuotaView } from "./principal-access-quota-view.js";

export interface PrincipalAccessModelRow {
  unified_model_id: string;
  display_name: string;
  alias: string;
  provider_code: string;
  provider_name: string;
  provider_resource_id: string;
  resource_name: string;
  mode: "API" | "CODING_PLAN";
  resource_status: string;
  model_status: string;
  route_enabled: boolean;
  ready: boolean;
  unavailable_reasons: string[];
}

export interface PrincipalAccessPoolRow {
  id: string;
  provider: string;
  quota_value: bigint;
  allow_overage: boolean;
  valid_until: Date | null;
  used_value: bigint;
  source: string;
  quota?: PrincipalAccessQuotaView;
}

/** 将仓储查询结果装配成按厂商分块的单主体接入读模型。 */
export function assemblePrincipalAccessReadModel(input: {
  principal: { id: string; name: string; status: string; department_label: string | null };
  key: { key_prefix: string; status: string; created_at: Date } | undefined;
  models: PrincipalAccessModelRow[];
  pools: PrincipalAccessPoolRow[];
  disabledKeys: Set<string>;
  /** Key 或有效 assignment 证明此前已明确配置过的型号。 */
  configuredModelIds?: string[];
  manualPendingIds: string[];
  configVersion: number;
}) {
  const configuredModelIds = new Set(input.configuredModelIds ?? []);
  const byProvider = new Map<string, { name: string; models: PrincipalAccessModelRow[] }>();
  for (const model of input.models) {
    const bucket = byProvider.get(model.provider_code) ?? { name: model.provider_name, models: [] };
    bucket.models.push(model);
    byProvider.set(model.provider_code, bucket);
  }
  const providers = [...byProvider.entries()].map(([code, bucket]) => {
    const pool = input.pools.find((item) => item.provider === code) ?? null;
    return {
      provider_code: code,
      provider_name: bucket.name,
      pool: pool ? {
        grant_id: pool.id,
        quota_value: pool.quota_value.toString(),
        quota_used: pool.quota?.mode === "MONTHLY" ? pool.quota.used_value! : pool.used_value.toString(),
        allow_overage: pool.allow_overage,
        valid_until: pool.valid_until,
        source: pool.source,
        over_limit: pool.quota?.mode === "MONTHLY"
          ? pool.quota.completeness === "COMPLETE" && BigInt(pool.quota.overage_value ?? "0") > 0n
          : pool.used_value > pool.quota_value,
        ...(pool.quota ? { quota: pool.quota } : {}),
      } : null,
      models: bucket.models.map((model) => ({
        unified_model_id: model.unified_model_id,
        display_name: model.display_name,
        alias: model.alias,
        provider_resource_id: model.provider_resource_id,
        resource_name: model.resource_name,
        resource_mode: model.mode,
        ready: model.ready,
        unavailable_reasons: model.unavailable_reasons,
        // enabled 表示持久化的授权意图，ready 表示当前是否可调用。
        // 资源耗尽等临时状态不能把既有授权伪装成“未开通”，否则下一次保存会误删配置。
        enabled: pool !== null
          && !input.disabledKeys.has(`${code}:${model.unified_model_id}`)
          && (model.ready || configuredModelIds.has(model.unified_model_id)),
      })),
    };
  });
  const enabledModelCount = providers.reduce(
    (count, provider) => count + provider.models.filter((model) => model.enabled).length,
    0,
  );
  return {
    principal: input.principal,
    key: input.key ? {
      key_prefix: input.key.key_prefix,
      status: input.key.status,
      created_at: input.key.created_at,
      authorization_status: enabledModelCount > 0 ? "AUTHORIZED" : "PENDING",
    } : null,
    providers,
    summary: {
      total_quota: input.pools.some((pool) => pool.quota)
        ? null : input.pools.reduce((total, pool) => total + pool.quota_value, 0n).toString(),
      ...(input.pools.some((pool) => pool.quota) ? { quota_aggregation: "PER_PROVIDER" as const } : {}),
      provider_count: input.pools.length,
      model_count: enabledModelCount,
    },
    manual_pending_takeover: input.manualPendingIds,
    config_version: input.configVersion,
  };
}

src/repositories/employee-model-rule-lif.source:
import type { Transaction } from "kysely";
import { matchApplicableBillingRule, type BillingResourceMode } from "@qianliu/domain";
import type { Database } from "../kysely.js";
import { mergeDeclaredModelIds } from "./employee-model-authorization-policy.js";
import { listEnabledBillingRulesAt } from "./billing-rule-applicability.js";

function jsonValue<T>(value: T): T {
  return JSON.stringify(value) as unknown as T;
}

function unique<T>(values: T[]): T[] {
  return [...new Set(values)];
}

/** 按手工基线、受管 assignment、厂商池与禁用清单重算 ACTIVE Key 白名单。 */
export async function refreshEmployeeKeyModels(
  trx: Transaction<Database>,
  enterpriseId: string,
  principalId: string,
): Promise<void> {
  const key = await trx.selectFrom("principal_key").select("id")
    .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
    .where("status", "=", "ACTIVE").forUpdate().executeTakeFirst();
  if (!key) return;
  const readyAt = new Date();
  const [manual, managed, disabled, billingRules] = await Promise.all([
    trx.selectFrom("principal_model_manual_authorization")
      .innerJoin("model_route", (join) => join
        .onRef("model_route.enterprise_id", "=", "principal_model_manual_authorization.enterprise_id")
        .onRef("model_route.unified_model_id", "=", "principal_model_manual_authorization.unified_model_id"))
      .innerJoin("unified_model", "unified_model.id", "model_route.unified_model_id")
      .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
      .innerJoin("provider", "provider.id", "provider_resource.provider_id")
      .select([
        "principal_model_manual_authorization.unified_model_id",
        "model_route.provider_resource_id",
        "model_route.upstream_model",
        "provider_resource.mode",
      ])
      .where("principal_model_manual_authorization.enterprise_id", "=", enterpriseId)
      .where("principal_model_manual_authorization.principal_id", "=", principalId)
      .where("unified_model.status", "=", "ACTIVE")
      .where("model_route.enabled", "=", true)
      .where("provider_resource.status", "in", ["ACTIVE", "DEGRADED"])
      .where("provider.status", "=", "ACTIVE")
      .execute(),
    trx.selectFrom("employee_model_rule_assignment")
      .innerJoin("principal_grant", "principal_grant.id", "employee_model_rule_assignment.grant_id")
      .innerJoin("model_route", (join) => join
        .onRef("model_route.enterprise_id", "=", "employee_model_rule_assignment.enterprise_id")
        .onRef("model_route.unified_model_id", "=", "employee_model_rule_assignment.unified_model_id")
        .onRef("model_route.provider_resource_id", "=", "employee_model_rule_assignment.provider_resource_id"))
      .innerJoin("unified_model", "unified_model.id", "model_route.unified_model_id")
      .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
      .innerJoin("provider", "provider.id", "provider_resource.provider_id")
      .select([
        "employee_model_rule_assignment.unified_model_id",
        "model_route.provider_resource_id",
        "model_route.upstream_model",
        "provider_resource.mode",
      ])
      .where("employee_model_rule_assignment.enterprise_id", "=", enterpriseId)
      .where("employee_model_rule_assignment.principal_id", "=", principalId)
      .where("employee_model_rule_assignment.status", "=", "ACTIVE")
      .where("principal_grant.status", "=", "ACTIVE")
      .where("principal_grant.valid_from", "<=", readyAt)
      .where((eb) => eb.or([
        eb("principal_grant.valid_until", "is", null),
        eb("principal_grant.valid_until", ">", readyAt),
      ]))
      .where("unified_model.status", "=", "ACTIVE")
      .where("model_route.enabled", "=", true)
      .where("provider_resource.status", "in", ["ACTIVE", "DEGRADED"])
      .where("provider.status", "=", "ACTIVE")
      .execute(),
    trx.selectFrom("principal_provider_disabled_model").select("unified_model_id")
      .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId).execute(),
    listEnabledBillingRulesAt(trx, enterpriseId, readyAt),
  ]);
  const poolModels = await trx.selectFrom("principal_grant")
    .innerJoin("model_route", (join) => join
      .onRef("model_route.enterprise_id", "=", "principal_grant.enterprise_id"))
    .innerJoin("unified_model", "unified_model.id", "model_route.unified_model_id")
    .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
    .innerJoin("provider", "provider.id", "provider_resource.provider_id")
    .select([
      "model_route.unified_model_id",
      "model_route.provider_resource_id",
      "model_route.upstream_model",
      "provider_resource.mode",
    ])
    .distinct()
    .where("principal_grant.enterprise_id", "=", enterpriseId)
    .where("principal_grant.principal_id", "=", principalId)
    .where("principal_grant.pool_model_alias", "=", "*")
    .where("principal_grant.status", "=", "ACTIVE")
    .where("principal_grant.valid_from", "<=", readyAt)
    .where((eb) => eb.or([
      eb("principal_grant.valid_until", "is", null),
      eb("principal_grant.valid_until", ">", readyAt),
    ]))
    .whereRef("provider.code", "=", "principal_grant.provider")
    // 厂商池只自动接纳当前就绪型号；发现但尚未配置的模型不得提前进入 Key 白名单。
    .where("unified_model.status", "=", "ACTIVE")
    .where("model_route.enabled", "=", true)
    .where("provider_resource.status", "in", ["ACTIVE", "DEGRADED"])
    .where("provider.status", "=", "ACTIVE")
    .execute();
  const isBillable = (row: {
    provider_resource_id: string;
    upstream_model: string;
    mode: string;
  }) => matchApplicableBillingRule(
    billingRules,
    row.provider_resource_id,
    row.upstream_model,
    row.mode as BillingResourceMode,
    readyAt.getTime(),
  ) !== null;
  const disabledSet = new Set(disabled.map((row) => row.unified_model_id));
  const manualAllowed = manual.filter(isBillable).map((row) => row.unified_model_id);
  const managedAllowed = managed.filter(isBillable).map((row) => row.unified_model_id);
  const poolAllowed = poolModels.filter(isBillable).map((row) => row.unified_model_id)
    .filter((id) => !disabledSet.has(id));
  const ids = mergeDeclaredModelIds(
    mergeDeclaredModelIds(manualAllowed, managedAllowed),
    poolAllowed,
  );
  await trx.updateTable("principal_key").set({ allowed_model_ids: jsonValue(ids) })
    .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
    .where("status", "=", "ACTIVE").execute();
}

/** 停用规则版本并撤销不再由其他规则维护的型号；共享厂商池保持 ACTIVE。 */
export async function disableEmployeeRuleVersion(
  trx: Transaction<Database>,
  enterpriseId: string,
  versionId: string,
  revokeModels = true,
): Promise<string[]> {
  const assignments = await trx.selectFrom("employee_model_rule_assignment")
    .select(["principal_id", "grant_id", "unified_model_id", "provider_resource_id"])
    .where("enterprise_id", "=", enterpriseId)
    .where("rule_version_id", "=", versionId).where("status", "=", "ACTIVE").forUpdate().execute();
  if (assignments.length > 0) {
    const now = new Date();
    await trx.updateTable("employee_model_rule_assignment").set({ status: "DISABLED", disabled_at: now })
      .where("rule_version_id", "=", versionId).where("status", "=", "ACTIVE").execute();
    const affectedPairs = new Map<string, {
      principal_id: string;
      unified_model_id: string;
      provider_resource_id: string;
    }>();
    for (const assignment of assignments) {
      affectedPairs.set(`${assignment.principal_id}:${assignment.unified_model_id}`, assignment);
    }
    for (const assignment of revokeModels ? affectedPairs.values() : []) {
      const stillMaintained = await trx.selectFrom("employee_model_rule_assignment")
        .select("id").where("enterprise_id", "=", enterpriseId)
        .where("principal_id", "=", assignment.principal_id)
        .where("unified_model_id", "=", assignment.unified_model_id)
        .where("status", "=", "ACTIVE").executeTakeFirst();
      if (!stillMaintained) {
        const route = await trx.selectFrom("model_route")
          .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
          .innerJoin("provider", "provider.id", "provider_resource.provider_id")
          .select("provider.code")
          .where("model_route.enterprise_id", "=", enterpriseId)
          .where("model_route.unified_model_id", "=", assignment.unified_model_id)
          .where("model_route.provider_resource_id", "=", assignment.provider_resource_id)
          .executeTakeFirst();
        if (route) {
          await trx.insertInto("principal_provider_disabled_model").values({
            enterprise_id: enterpriseId,
            principal_id: assignment.principal_id,
            provider: route.code,
            unified_model_id: assignment.unified_model_id,
            disabled_at: now,
            disable_rule_version_id: versionId,
          }).onConflict((oc) => oc.doNothing()).execute();
        }
      }
    }
    if (revokeModels) {
      for (const principalId of unique(assignments.map((row) => row.principal_id)).sort()) {
        await refreshEmployeeKeyModels(trx, enterpriseId, principalId);
      }
    }
  }
  await trx.updateTable("employee_model_rule_version")
    .set({ status: "DISABLED", disabled_at: new Date(), updated_at: new Date() })
    .where("id", "=", versionId).execute();
  return unique(assignments.map((row) => row.principal_id));
}

src/repositories/employee-model-rule-loc.source:
import type { Transaction } from "kysely";
import type { Database } from "../kysely.js";
import { lockActivePrincipalKeys } from "./principal-access-locks.js";

export interface RuleLockReference {
  rule_id: string;
  employee_scope: "SELECTED" | "ALL";
  principal_ids: string[];
}

export async function lockVersion(
  trx: Transaction<Database>,
  enterpriseId: string,
  versionId: string,
) {
  return trx.selectFrom("employee_model_rule_version").selectAll()
    .where("enterprise_id", "=", enterpriseId).where("id", "=", versionId)
    .forUpdate().executeTakeFirst();
}

export async function readRuleReference(
  trx: Transaction<Database>,
  enterpriseId: string,
  versionId: string,
): Promise<RuleLockReference | undefined> {
  return trx.selectFrom("employee_model_rule_version")
    .select(["rule_id", "employee_scope", "principal_ids"])
    .where("enterprise_id", "=", enterpriseId).where("id", "=", versionId)
    .executeTakeFirst();
}

export async function principalIdsForRuleFamily(
  trx: Transaction<Database>,
  enterpriseId: string,
  reference: RuleLockReference,
): Promise<string[]> {
  const ids = reference.employee_scope === "SELECTED"
    ? reference.principal_ids
    : (await trx.selectFrom("principal").select("id")
      .where("enterprise_id", "=", enterpriseId).where("type", "=", "EMPLOYEE")
      .execute()).map((row) => row.id);
  const publishedVersionIds = (await trx.selectFrom("employee_model_rule_version").select("id")
    .where("enterprise_id", "=", enterpriseId).where("rule_id", "=", reference.rule_id)
    .where("status", "=", "PUBLISHED").execute()).map((row) => row.id);
  const assignments = publishedVersionIds.length === 0 ? [] : await trx.selectFrom("employee_model_rule_assignment")
    .select("principal_id").where("enterprise_id", "=", enterpriseId)
    .where("rule_version_id", "in", publishedVersionIds).execute();
  return [...new Set([...ids, ...assignments.map((row) => row.principal_id)])]
    .sort((left, right) => left.localeCompare(right, "en"));
}

export async function lockRuleFamily(
  trx: Transaction<Database>,
  enterpriseId: string,
  versionId: string,
  captureManualBaseline: (trx: Transaction<Database>, enterpriseId: string, principalId: string) => Promise<void>,
): Promise<{ reference: RuleLockReference | undefined; principals: string[] }> {
  const reference = await readRuleReference(trx, enterpriseId, versionId);
  if (!reference) return { reference: undefined, principals: [] };
  const principals = await principalIdsForRuleFamily(trx, enterpriseId, reference);
  await lockActivePrincipalKeys(trx, enterpriseId, principals);
  for (const principalId of principals) await captureManualBaseline(trx, enterpriseId, principalId);
  return { reference, principals };
}

export async function captureManualBaseline(
  trx: Transaction<Database>,
  enterpriseId: string,
  principalId: string,
): Promise<void> {
  const existing = await trx.selectFrom("principal_model_manual_authorization").select("unified_model_id")
    .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId).execute();
  const key = await trx.selectFrom("principal_key").select("allowed_model_ids")
    .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
    .where("status", "=", "ACTIVE").forUpdate().executeTakeFirst();
  if (!key) return;
  const managed = await trx.selectFrom("employee_model_rule_assignment").select("unified_model_id")
    .where("enterprise_id", "=", enterpriseId).where("principal_id", "=", principalId)
    .where("status", "=", "ACTIVE").execute();
  const managedIds = new Set(managed.map((row) => row.unified_model_id));
  const existingIds = new Set(existing.map((row) => row.unified_model_id));
  // 批量授权是增量合同：发布前把当前 Key 后来增加的未受管型号持续并入基线，
  // 不能因为曾经捕获过一条旧基线就跳过；受管型号仍由 assignment／厂商池维护。
  const manualIds = (key.allowed_model_ids ?? [])
    .filter((id) => !managedIds.has(id) && !existingIds.has(id));
  if (manualIds.length > 0) await trx.insertInto("principal_model_manual_authorization")
    .values(manualIds.map((unified_model_id) => ({ enterprise_id: enterpriseId, principal_id: principalId, unified_model_id })))
    .onConflict((oc) => oc.doNothing()).execute();
}

export async function providerCodesForRuleFamily(
  trx: Transaction<Database>,
  enterpriseId: string,
  ruleId: string,
  modelScope: "SELECTED" | "ALL",
  modelTargets: { unified_model_id: string; provider_resource_id: string }[],
): Promise<string[]> {
  const routes = await trx.selectFrom("model_route")
    .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
    .innerJoin("provider", "provider.id", "provider_resource.provider_id")
    .select("provider.code").where("model_route.enterprise_id", "=", enterpriseId)
    .$if(modelScope === "SELECTED", (qb) => qb.where((eb) => eb.or(
      modelTargets.map((target) => eb.and([
        eb("model_route.unified_model_id", "=", target.unified_model_id),
        eb("model_route.provider_resource_id", "=", target.provider_resource_id),
      ])),
    ))).execute();
  const previousRoutes = await trx.selectFrom("employee_model_rule_assignment")
    .innerJoin("model_route", (join) => join
      .onRef("model_route.unified_model_id", "=", "employee_model_rule_assignment.unified_model_id")
      .onRef("model_route.provider_resource_id", "=", "employee_model_rule_assignment.provider_resource_id")
      .onRef("model_route.enterprise_id", "=", "employee_model_rule_assignment.enterprise_id"))
    .innerJoin("provider_resource", "provider_resource.id", "model_route.provider_resource_id")
    .innerJoin("provider", "provider.id", "provider_resource.provider_id")
    .innerJoin("employee_model_rule_version", "employee_model_rule_version.id", "employee_model_rule_assignment.rule_version_id")
    .select("provider.code").where("employee_model_rule_assignment.enterprise_id", "=", enterpriseId)
    .where("employee_model_rule_assignment.status", "=", "ACTIVE")
    .where("employee_model_rule_version.rule_id", "=", ruleId).execute();
  return [...new Set([...routes, ...previousRoutes].map((row) => row.code))]
    .sort((left, right) => left.localeCompare(right, "en"));
}

