    .executeTakeFirstOrThrow();
  await db
    .insertInto("ai_request")
    .values({
      id: requestId,
      enterprise_id: enterpriseId,
      principal_id: principalId,
      principal_key_id: key.id,
      status: "IN_PROGRESS",
      protocol: "OPENAI",
